         tensor->bytes, crc32_raw(memory, tensor->bytes), path);
  file = fopen(path, "wb");
  if (file == NULL)
    {
      fprintf(stderr, "open output '%s' failed: %s\n", path, strerror(errno));
      vip_unmap_buffer(tensor->handle);
      return -1;
    }

  actual = fwrite(memory, 1, tensor->bytes, file);
